const respuesta = pm.response.json();

pm.test("La API responde 201 (usuario creado)", function () {
    pm.response.to.have.status(201);
});

pm.test("El nombre y el trabajo son los mismos que envié", function () {
    pm.expect(respuesta.name).to.eql(pm.environment.get("user_name"));
    pm.expect(respuesta.job).to.eql(pm.environment.get("user_job"));
});

pm.test("La respuesta trae el id y la fecha de creación", function () {
    pm.expect(respuesta.id).to.exist;
    pm.expect(respuesta.createdAt).to.exist;
});

// Guardo el id para usarlo en el siguiente caso de prueba
pm.environment.set("user_id", respuesta.id);

// TC02 - Consultar usuario creado
// Objetivo: verificar que el usuario creado en el TC01 se pueda consultar
// y que sus datos sean los mismos que se enviaron al crearlo.

// Validación 1: la API debe encontrar el usuario y responder 200
pm.test("La API responde 200 (encontró el usuario)", function () {
    pm.response.to.have.status(200);
});

// Validación 2: el nombre y el trabajo deben coincidir con los del TC01
pm.test("El nombre y el trabajo son los mismos que envié al crearlo", function () {
    // Leo lo que respondió la API
    const respuesta = pm.response.json();
    // Algunas respuestas traen los datos dentro de "data", por eso reviso ambos casos
    const usuario = respuesta.data || respuesta;
    // Comparo con los datos guardados en el environment
    pm.expect(usuario.name).to.eql(pm.environment.get("user_name"));
    pm.expect(usuario.job).to.eql(pm.environment.get("user_job"));
});

// TC03 - Consultar un usuario que sí existe
// Objetivo: comprobar que el GET funciona con un usuario que ya existe en Reqres.
// Esto confirma que el 404 del TC02 no es por la consulta, sino porque la API no guarda los usuarios creados.

// Validación 1: la API debe encontrar el usuario
pm.test("La API responde 200 (encontró el usuario)", function () {
    pm.response.to.have.status(200);
});

// Validación 2: el usuario debe traer sus datos básicos
pm.test("El usuario trae id, correo, nombre y apellido", function () {
    const usuario = pm.response.json().data;
    pm.expect(usuario.id).to.eql(2);
    pm.expect(usuario.email).to.exist;
    pm.expect(usuario.first_name).to.exist;
    pm.expect(usuario.last_name).to.exist;
});

// TC04 - Consultar un usuario que no existe
// Objetivo: comprobar que la API avisa correctamente cuando el usuario no existe.

// Validación 1: la API debe responder que no encontró el usuario
pm.test("La API responde 404 (usuario no encontrado)", function () {
    pm.response.to.have.status(404);
});

// Validación 2: la respuesta no debe traer datos
pm.test("La respuesta viene vacía", function () {
    pm.expect(pm.response.json()).to.eql({});
});

// TC05 - Crear un usuario sin datos
// Objetivo: comprobar que la API no permita crear un usuario sin nombre ni trabajo.
// Una API bien construida debería rechazarlo con un error 400 (petición incorrecta).

pm.test("La API rechaza el usuario sin datos (400)", function () {
    pm.response.to.have.status(400);
});
